#include <iostream>
#include <sstream>
#include <string>

int main() {
    std::istringstream entrada{"sol\nresto\n"};
    char texto[4]{};
    entrada.getline(texto, 4);
    const bool fallo = entrada.fail();
    const bool fin = entrada.eof();
    const auto extraidos = entrada.gcount();
    std::string siguiente;

    std::getline(entrada, siguiente);

    std::cout << '[' << texto << "]:" << fallo << ':' << fin << ':'
              << extraidos << ":[" << siguiente << ']';
    return 0;
}

