#include <iostream>
#include <sstream>
#include <string>

int main() {
    std::istringstream entrada{"soles\nfin\n"};
    char primera[4]{};
    char segunda[4]{'X', 'Y', 'Z', '\0'};
    entrada.getline(primera, 4);
    const bool fallo = entrada.fail();
    const auto extraidos = entrada.gcount();
    entrada.getline(segunda, 4);
    entrada.clear();
    std::string resto;

    std::getline(entrada, resto);

    std::cout << '[' << primera << "]:" << fallo << ':' << extraidos
              << ":[" << segunda << "]:[" << resto << ']';
    return 0;
}

#include <limits>
#include <iostream>
#include <sstream>
#include <string>

int main() {
    std::istringstream entrada{"planeta\nfin\n"};
    char primera[5]{};
    char segunda[5]{};
    entrada.getline(primera, 5);
    const bool fallo = entrada.fail();
    entrada.clear();
    entrada.ignore(std::numeric_limits<std::streamsize>::max(), '\n');
    entrada.getline(segunda, 5);
    std::cout << '[' << primera << "]:" << fallo << ":[" << segunda
              << "]:" << entrada.fail();
    return 0;
}

#include <cstring>
