#include <iostream>
#include <limits>
#include <string>

int main() {
    char candidato[6]{};

    std::cin.getline(candidato, 6);

    const bool fallo = std::cin.fail();
    const bool fin = std::cin.eof();

    if (std::cin.bad()) {
        return 2;
    }
    std::string registro = "base";
    bool aceptado = false;
    std::string siguiente;
    bool haySiguiente = false;

    if (!fallo) {
        registro = candidato;
        aceptado = true;
    } else if (!fin) {
        std::cin.clear();
        std::cin.ignore(std::numeric_limits<std::streamsize>::max(), '\n');
    }
    haySiguiente = static_cast<bool>(std::getline(std::cin, siguiente));

    std::cout << "Lectura=" << fallo << ':' << fin << '\n';
    std::cout << "Aceptado=" << aceptado << '\n';
    std::cout << "Registro=[" << registro << "]\n";
    std::cout << "Siguiente=" << haySiguiente << ":[" << siguiente << "]\n";

    return 0;
}

